solutions.naive:
class Solution:
    def hammingWeight(self, n: int) -> int:
        # Mask keeps the representation within unsigned 32-bit behavior.
        bits = bin(n & 0xFFFFFFFF)
        count = 0
        for ch in bits:
            if ch == "1":
                count += 1
        return count

solutions.better:
class Solution:
    def hammingWeight(self, n: int) -> int:
        n &= 0xFFFFFFFF
        count = 0
        for i in range(32):
            if n & (1 << i):
                count += 1
        return count

solutions.optimal:
class Solution:
    def hammingWeight(self, n: int) -> int:
        n &= 0xFFFFFFFF
        count = 0
        while n:
            # Clears the rightmost 1 bit.
            n &= n - 1
            count += 1
        return count

